#!/usr/bin/env python3
"""MEMRA_REQUEST_LOG device A/B: generated bytes with the log off and on.

Boots the given memra-server binary once per arm, in the order A B B A (A = log off, B = log
on), on the same model, and replays one fixed greedy request set per boot: two-turn chat
sessions (an explicit session_id and an unnamed one), blocking and streaming, with tools; raw
completions blocking and streaming (native shape, so token ids are on the wire); one Responses
and one Messages request. Every response is reduced to what the model produced and the server
shaped around it (per-response ids, creation stamps and wall-clock fields removed) and the four
boots must agree byte for byte. The B boots' log lines are checked against the responses.

Usage: ab.py --bin target/release/memra-server --model m=/path.gguf --out DIR [--port 8191]
Exit 0 only when every boot answered and all four agree.
"""
from __future__ import annotations

import argparse
import hashlib
import http.client
import json
import os
import subprocess
import sys
import time
from pathlib import Path

TOOLS = [{"type": "function", "function": {
    "name": "get_weather",
    "description": "Current weather for a city.",
    "parameters": {"type": "object",
                   "properties": {"city": {"type": "string", "description": "City name"}},
                   "required": ["city"]}}}]
SYSTEM = "You are a weather assistant. Call get_weather when the user asks about weather."


def chat_turns(first_user: str, second: bool) -> list:
    msgs = [{"role": "system", "content": SYSTEM}, {"role": "user", "content": first_user}]
    if second:
        msgs += [{"role": "assistant", "content": "It is sunny there right now."},
                 {"role": "user", "content": "What should I wear tomorrow?"}]
    return msgs


def request_set(model: str) -> list:
    """(name, path, body). Greedy everywhere; fixed max_tokens so every boot does equal work."""
    base = {"model": model, "temperature": 0, "max_tokens": 96}
    out = []
    for tag, ident in (("named", {"session_id": "ab-session-1"}), ("unnamed", {})):
        out.append((f"chat-{tag}-t1", "/v1/chat/completions",
                    {**base, **ident, "messages": chat_turns("Weather in Paris?", False),
                     "tools": TOOLS}))
        out.append((f"chat-{tag}-t2-stream", "/v1/chat/completions",
                    {**base, **ident, "messages": chat_turns("Weather in Paris?", True),
                     "tools": TOOLS, "stream": True}))
    out.append(("completion", "/v1/completions",
                {**base, "prompt": "The three primary colors are", "user": "ab-user"}))
    out.append(("completion-stream", "/v1/completions",
                {**base, "prompt": "The three primary colors are", "stream": True}))
    out.append(("responses", "/v1/responses",
                {"model": model, "temperature": 0, "max_output_tokens": 64,
                 "input": "Name two rivers in Europe."}))
    out.append(("messages", "/v1/messages",
                {"model": model, "temperature": 0, "max_tokens": 64,
                 "messages": [{"role": "user", "content": "Name two mountains in Asia."}]}))
    return out


# Per-response identity and wall-clock fields: everything else must be byte-identical.
SCRUB = {"id", "created", "created_at", "elapsed_s", "system_fingerprint", "completed_at"}


def scrub(v):
    if isinstance(v, dict):
        return {k: scrub(x) for k, x in v.items() if k not in SCRUB}
    if isinstance(v, list):
        return [scrub(x) for x in v]
    return v


def normalize(content_type: str, body: bytes) -> list:
    text = body.decode("utf-8")
    if content_type.startswith("text/event-stream"):
        rows = []
        for line in text.splitlines():
            if line.startswith("event: "):
                rows.append(line)
            elif line.startswith("data: "):
                data = line[len("data: "):]
                try:
                    rows.append(json.dumps(scrub(json.loads(data)), sort_keys=True))
                except json.JSONDecodeError:
                    rows.append(data)
        return rows
    return [json.dumps(scrub(json.loads(text)), sort_keys=True)]


def post(port: int, path: str, body: dict, timeout: float = 300.0):
    conn = http.client.HTTPConnection("127.0.0.1", port, timeout=timeout)
    conn.request("POST", path, json.dumps(body), {"content-type": "application/json"})
    resp = conn.getresponse()
    data = resp.read()
    rid = resp.getheader("x-request-id") or ""
    ctype = resp.getheader("content-type") or ""
    conn.close()
    return resp.status, ctype, rid, data


def wait_ready(port: int, proc: subprocess.Popen, deadline_s: float) -> bool:
    end = time.monotonic() + deadline_s
    while time.monotonic() < end:
        if proc.poll() is not None:
            return False
        try:
            conn = http.client.HTTPConnection("127.0.0.1", port, timeout=2)
            conn.request("GET", "/readyz")
            ok = conn.getresponse().status == 200
            conn.close()
            if ok:
                return True
        except OSError:
            pass
        time.sleep(1)
    return False


def boot(args, arm: str, idx: int, out: Path) -> dict:
    run = out / f"boot{idx}-{arm}"
    run.mkdir(parents=True, exist_ok=False)
    env = {k: v for k, v in os.environ.items() if not k.startswith("MEMRA_")}
    env.update({"MEMRA_MODELS": args.model, "MEMRA_ADDR": f"127.0.0.1:{args.port}"})
    for kv in args.env:
        k, _, v = kv.partition("=")
        env[k] = v
    log_path = run / "requests.jsonl"
    if arm == "on":
        env["MEMRA_REQUEST_LOG"] = str(log_path)
    with open(run / "server.log", "wb") as server_log:
        proc = subprocess.Popen([args.bin], env=env, stdout=server_log, stderr=subprocess.STDOUT)
        try:
            if not wait_ready(args.port, proc, args.boot_timeout):
                raise SystemExit(f"boot {idx} ({arm}) not ready; see {run / 'server.log'}")
            results = {}
            for name, path, body in request_set(args.model.split("=", 1)[0]):
                status, ctype, rid, data = post(args.port, path, body)
                (run / f"{name}.body").write_bytes(data)
                results[name] = {"status": status, "content_type": ctype, "request_id": rid,
                                 "normalized": normalize(ctype, data) if status == 200 else
                                 [data.decode("utf-8", "replace")]}
        finally:
            proc.terminate()
            try:
                proc.wait(timeout=120)
            except subprocess.TimeoutExpired:
                proc.kill()
                proc.wait()
    (run / "results.json").write_text(json.dumps(results, indent=1, sort_keys=True))
    return {"arm": arm, "results": results, "log": log_path if arm == "on" else None}


def check_log(boot_rec: dict) -> list:
    """The B boots' lines against their own responses. Returns failures."""
    fails = []
    lines = [json.loads(l) for l in Path(boot_rec["log"]).read_text().splitlines()]
    by_id = {l["request_id"]: l for l in lines}
    res = boot_rec["results"]
    if len(lines) != len(res):
        fails.append(f"{len(lines)} lines for {len(res)} requests")
    for name, r in res.items():
        line = by_id.get(r["request_id"])
        if line is None:
            fails.append(f"{name}: no line for {r['request_id']}")
            continue
        for field in ("t_arrival", "t_first_token", "t_end"):
            if not isinstance(line.get(field), float):
                fails.append(f"{name}: {field}={line.get(field)!r}")
        if isinstance(line.get("t_first_token"), float) and not (
                line["t_arrival"] <= line["t_first_token"] <= line["t_end"]):
            fails.append(f"{name}: times out of order {line}")
        if line.get("http_status") != r["status"]:
            fails.append(f"{name}: http_status {line.get('http_status')} vs {r['status']}")
        if line.get("end_reason") not in ("stop", "length"):
            fails.append(f"{name}: end_reason {line.get('end_reason')}")
        if not line.get("prompt_sha256") or not line.get("generated_tokens"):
            fails.append(f"{name}: missing prompt_sha256/generated_tokens {line}")
    pair = [by_id.get(res[n]["request_id"], {}) for n in ("chat-named-t1", "chat-named-t2-stream")]
    if pair[0].get("session_key") != hashlib.sha256(b"ab-session-1").hexdigest() or \
            pair[0].get("session_key") != pair[1].get("session_key"):
        fails.append(f"named session keys {[p.get('session_key') for p in pair]}")
    pair = [by_id.get(res[n]["request_id"], {}) for n in ("chat-unnamed-t1", "chat-unnamed-t2-stream")]
    if not pair[0].get("session_key") or pair[0].get("session_key") != pair[1].get("session_key") \
            or pair[0].get("session_key_source") != "fingerprint":
        fails.append(f"unnamed session keys {[(p.get('session_key'), p.get('session_key_source')) for p in pair]}")
    comp = by_id.get(res["completion"]["request_id"], {})
    if comp.get("session_key") != hashlib.sha256(b"ab-user").hexdigest() or comp.get("tool_calls") is not None:
        fails.append(f"completion line {comp}")
    return fails


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--bin", required=True)
    ap.add_argument("--model", required=True, help="MEMRA_MODELS value, name=path[+draft]")
    ap.add_argument("--out", required=True)
    ap.add_argument("--port", type=int, default=8191)
    ap.add_argument("--boot-timeout", type=float, default=600.0)
    ap.add_argument("--env", action="append", default=[], help="extra KEY=VALUE for every boot")
    args = ap.parse_args()
    out = Path(args.out)
    out.mkdir(parents=True, exist_ok=True)
    binary = Path(args.bin).read_bytes()
    meta = {"bin": args.bin, "bin_sha256": hashlib.sha256(binary).hexdigest(),
            "model": args.model, "env": args.env, "order": "A B B A (A=log off, B=log on)",
            "started": time.strftime("%Y-%m-%dT%H:%M:%S%z")}
    boots = [boot(args, arm, i, out) for i, arm in enumerate(("off", "on", "on", "off"))]
    names = list(boots[0]["results"])
    diffs = []
    for name in names:
        ref = boots[0]["results"][name]
        if ref["status"] != 200:
            diffs.append(f"{name}: boot0 status {ref['status']}")
        for i, b in enumerate(boots[1:], 1):
            r = b["results"][name]
            if (r["status"], r["normalized"]) != (ref["status"], ref["normalized"]):
                diffs.append(f"{name}: boot{i} ({b['arm']}) differs from boot0 (off)")
    log_fails = []
    for i, b in enumerate(boots):
        if b["arm"] == "on":
            log_fails += [f"boot{i}: {f}" for f in check_log(b)]
    verdict = "PASS" if not diffs and not log_fails else "FAIL"
    summary = {**meta, "finished": time.strftime("%Y-%m-%dT%H:%M:%S%z"), "requests": names,
               "byte_diffs": diffs, "log_failures": log_fails, "verdict": verdict,
               "normalized_sha256": {n: hashlib.sha256(json.dumps(
                   boots[0]["results"][n]["normalized"]).encode()).hexdigest() for n in names}}
    (out / "summary.json").write_text(json.dumps(summary, indent=1, sort_keys=True))
    print(f"request-log A/B: {verdict} ({len(names)} requests x 4 boots; "
          f"{len(diffs)} byte diffs, {len(log_fails)} log failures)")
    for line in diffs + log_fails:
        print("  " + line)
    return 0 if verdict == "PASS" else 1


if __name__ == "__main__":
    sys.exit(main())
